import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'admin', 'sk-admin-9f8e7d6c')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('service', 'svc@corp.internal', 'service', 'sk-svc-1a2b3c4d')")
    db.commit()
    db.close()

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Log the search for audit purposes
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field}, query={value}')"
    try:
        db.execute(log_query)
        db.commit()
    except Exception:
        pass  # Non-critical, don't fail the request

    # Perform the actual search using parameterized query
    search_query = f"SELECT username, email, role FROM users WHERE {field} LIKE ?"
    try:
        cursor = db.execute(search_query, (f'%{value}%',))
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/lookup', methods=['GET'])
def lookup_user():
    """Lookup user by exact username match."""
    username = request.args.get('username', '')
    if not username:
        return jsonify({'error': 'username parameter required'}), 400

    db = get_db()
    # Direct string formatting for the lookup query
    query = f"SELECT username, email, role FROM users WHERE username = '{username}'"
    try:
        cursor = db.execute(query)
        row = cursor.fetchone()
        if row:
            return jsonify({'user': dict(row)})
        return jsonify({'error': 'User not found'}), 404
    except Exception as e:
        return jsonify({'error': 'Lookup failed'}), 500

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.1.4'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
